SELECT C.ID, C.NOME, C.HANDLE, C.URL, C.THUMB, C.CARGA_STATUS, C.CARGA_MSG, C.ULTIMA_CHECAGEM, C.CRIADO_EM, SUM(V.STATUS = 'ESTUDADO') ESTUDADOS, SUM(V.STATUS = 'FILA') FILA, SUM(V.STATUS = 'PENDENTE') PENDENTES, SUM(V.STATUS = 'FILA' AND V.ORIGEM = 'AUDIO') SEM_LEGENDA, SUM(V.STATUS <> 'FORA') TOTAL FROM CANAIS C LEFT JOIN VIDEOS V ON V.CANAL_ID = C.ID GROUP BY C.ID, C.NOME, C.HANDLE, C.URL, C.THUMB, C.CARGA_STATUS, C.CARGA_MSG, C.ULTIMA_CHECAGEM, C.CRIADO_EM ORDER BY C.ID